def event_sequence(value: Any) -> int:
    """Return an event's sequence number, or `0` when it carries none.

    A stored sequence is normally a number; a document that carries something
    else is not a reason to abandon the judgement, so the value is treated as
    absent instead.
    """
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0

