    @staticmethod
    def _accepted_texts(text: str, variants: Any) -> tuple[str, ...]:
        """Return the exact text plus the exact variants a task also accepts.

        The English brief quotes some texts with the sentence or list
        punctuation inside the closing quote (“Draft issue tracked.”, “Timeline
        owner set,”), so a reader cannot tell whether that mark belongs to the
        text.  Such a task lists the other reading as a variant; every variant
        is still compared exactly.
        """
        accepted = [text]
        if isinstance(variants, (list, tuple)):
            accepted.extend(str(item) for item in variants if str(item or ""))
        return tuple(dict.fromkeys(accepted))

    @classmethod
    def _matching_comments(
        cls,
        comments: Mapping[str, Any],
        post_id: str,
        expected_handle: str,
        text: str | tuple[str, ...] | list[str],
        created_after: str,
    ) -> list[Mapping[str, Any]]:
        texts = (text,) if isinstance(text, str) else tuple(text)
        return [
            item
            for item in (comments.get(post_id) or [])
            if isinstance(item, Mapping)
            and str(item.get("authorHandle") or "") == expected_handle
            and str(item.get("text") or "") in texts
            and cls._created_after(item.get("createdAt"), created_after)
        ]

    @staticmethod
    def _created_after(raw: Any, threshold: str) -> bool:
        if not threshold:
            return bool(str(raw or "").strip())
        try:
            observed = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
            expected = datetime.fromisoformat(threshold.replace("Z", "+00:00"))
            if observed.tzinfo is None:
                observed = observed.replace(tzinfo=timezone.utc)
            if expected.tzinfo is None:
                expected = expected.replace(tzinfo=timezone.utc)
            return observed >= expected
        except (TypeError, ValueError):
            return False

    @staticmethod
    def _read_dom_state(controller: Any, app_package: str) -> dict[str, Any]:
        pid = str(controller.execute_adb(["shell", "pidof", app_package]) or "").strip().split()
        if not pid:
            raise RuntimeError(f"OpenTwitter process is not running: {app_package}")
        port = _free_tcp_port()
        forward_spec = f"tcp:{port}"
        controller.execute_adb(["forward", forward_spec, f"localabstract:webview_devtools_remote_{pid[0]}"])
        try:
            with urlopen(f"http://127.0.0.1:{port}/json", timeout=4.0) as response:
                targets = json.loads(response.read().decode("utf-8"))
            target = next(
                item
                for item in targets
                if isinstance(item, Mapping) and str(item.get("webSocketDebuggerUrl") or "").strip()
            )
            expression = (
                "JSON.stringify({"
                "view:(typeof appState==='object'&&appState?String(appState.view||''):''),"
                "active_message_handle:(typeof appState==='object'&&appState?String(appState.activeMessageHandle||''):''),"
                "message_thread_open:(typeof appState==='object'&&appState?Boolean(appState.messageThreadOpen):false),"
                "body_text:String(document.body&&document.body.innerText||'')"
                "})"
            )
            raw = _devtools_runtime_evaluate(str(target["webSocketDebuggerUrl"]), expression)
            payload = json.loads(str(raw or "{}"))
            return payload if isinstance(payload, dict) else {}
        finally:
            controller.execute_adb(["forward", "--remove", forward_spec])
